const state = { clicks: 0, error: '' };

function clickLearn() {
  state.clicks += 1;
  return `已点击 ${state.clicks} 次`;
}

function validateCourseName(name) {
  state.error = name.trim() ? '' : '请输入课程名称';
  return state.error || '可以提交';
}

console.log(clickLearn());
console.log(clickLearn());
console.log(validateCourseName(''));
console.log(validateCourseName('Amazing Teaching'));
